// Consolide les reponses Meta en une ligne par compte,
// dans l'ordre des colonnes de prototype/reseaux.html.

const cfg = $('Config').first().json;

// --- somme d'une serie 'day' renvoyee par /insights ---
function sumMetric(payload, name) {
  const serie = (payload.data || []).find((m) => m.name === name);
  if (!serie) return null;
  return (serie.values || []).reduce((total, v) => total + (Number(v.value) || 0), 0);
}

// --- derniere valeur connue d'une serie 'day' ---
function lastMetric(payload, name) {
  const serie = (payload.data || []).find((m) => m.name === name);
  if (!serie || !serie.values || !serie.values.length) return null;
  return Number(serie.values[serie.values.length - 1].value) || 0;
}

const fbPage = $('FB - compte').first().json;
const fbIns = $('FB - statistiques').first().json;
const fbPosts = $('FB - publications 30j').first().json;
const igUser = $('IG - compte').first().json;
const igIns = $('IG - statistiques').first().json;
const igMedia = $('IG - publications 30j').first().json;

// ---------- Facebook ----------
const fbImpressions = sumMetric(fbIns, 'page_impressions');
const fbEngagements = sumMetric(fbIns, 'page_post_engagements');
const facebook = {
  reseau: 'facebook',
  compte: fbPage.name || null,
  externalMetaId: fbPage.id || null,
  publications30j: (fbPosts.data || []).length,
  abonnes: fbPage.followers_count ?? fbPage.fan_count ?? lastMetric(fbIns, 'page_follows'),
  vuesProfil30j: sumMetric(fbIns, 'page_views_total'),
  // engagement = interactions / affichages, sur 30 jours
  engagementPct: fbImpressions ? Number(((fbEngagements / fbImpressions) * 100).toFixed(2)) : null,
  posts30jTronque: (fbPosts.paging && fbPosts.paging.next) ? true : false,
};

// ---------- Instagram ----------
const medias = igMedia.data || [];
const interactions = medias.reduce(
  (total, m) => total + (Number(m.like_count) || 0) + (Number(m.comments_count) || 0),
  0,
);
const abonnesIg = Number(igUser.followers_count) || 0;
const instagram = {
  reseau: 'instagram',
  compte: igUser.username || null,
  externalMetaId: igUser.id || null,
  publications30j: medias.length,
  publicationsTotal: igUser.media_count ?? null,
  abonnes: abonnesIg || null,
  vuesProfil30j: sumMetric(igIns, 'profile_views'),
  portee30j: sumMetric(igIns, 'reach'),
  // engagement = interactions moyennes par publication / abonnes
  engagementPct:
    medias.length && abonnesIg
      ? Number(((interactions / medias.length / abonnesIg) * 100).toFixed(2))
      : null,
  medias30jTronque: (igMedia.paging && igMedia.paging.next) ? true : false,
};

// ---------- indicateurs manquants, a verifier pendant le test ----------
const aVerifier = [];
if (facebook.vuesProfil30j === null) aVerifier.push('page_views_total absent de la reponse Facebook');
if (fbImpressions === null) aVerifier.push('page_impressions absent : engagement Facebook non calculable');
if (instagram.vuesProfil30j === null) aVerifier.push('profile_views absent de la reponse Instagram');
if (instagram.portee30j === null) aVerifier.push('reach absent de la reponse Instagram');

return [
  {
    json: {
      collecteLe: new Date().toISOString(),
      periodeJours: cfg.days,
      comptes: [facebook, instagram],
      aVerifier,
    },
  },
];
